Here is the Python code to answer the questions based on the given table and question:
```python
# Define the table including the header
table = [
    ["Competition", "Total spectatorship", "Average match attendance", "Year"],
    ["A-League", 1772133, 12707, "2012/2013"],
    ["Australian Football League", 6931085, 33484, "2013"],
    ["Big Bash League", 550262, 17750, "2011/2012"],
    ["National Basketball League", 547021, 4031, "2010/2011"],
    ["National Rugby League", 3345248, 16643, "2013"],
    ["Super Rugby", 773940, 19348, "2012"],
    ["Rugby Championship", 133532, 44511, "2012"],
    ["State of Origin series", 186607, 62202, "2011"],
    ["Women's National Basketball League", 77944, None, "2010/2011"],
]

# Initialize the ans list
ans = []

# Loop through each question
for question in ['what year did average match attendance go below 10,000 for any australian sport?', 'what is the total spectatorship for the year 2013 national rugby league?', 'what was the total spectators for the national ruby league in 2013?', 'which were held in 2013?', 'which sport saw the attendance drop below 10,000 for 2010/2011?', 'which competition had an average attendance of 4031?']:
    # Initialize the answer as an empty string
    answer = ''

    # Check what question it is
    if question == 'what year did average match attendance go below 10,000 for any australian sport?':
        years_below_10000 = []
        for row in table[1:]:
            if row[2] and row[2] < 10000:
                years_below_10000.append(row[3])
        answer = ', '.join(years_below_10000)
    elif question == 'what is the total spectatorship for the year 2013 national rugby league?':
        for row in table:
            if row[0] == 'National Rugby League' and row[3] == '2013':
                answer = row[1]
    elif question == 'what was the total spectators for the national ruby league in 2013?':
        for row in table:
            if row[0] == 'National Rugby League' and row[3] == '2013':
                answer = row[1]
    elif question == 'which were held in 2013?':
        competitions_in_2013 = []
        for row in table[1:]:
            if row[3] == '2013':
                competitions_in_2013.append(row[0])
        answer = ', '.join(competitions_in_2013)
    elif question == 'which sport saw the attendance drop below 10,000 for 2010/2011?':
        for row in table[1:]:
            if row[2] and row[2] < 10000 and row[3] == '2010/2011':
                answer = row[0]
    elif question == 'which competition had an average attendance of 4031?':
        for row in table[1:]:
            if row[2] == 4031:
                answer = row[0]

    # Append the answer to the ans list
    ans.append(answer)

# Print the ans list
print(ans)
```
